import {setupSpotifyPlayer} from './spotify-player.js';
import {isFeatureActivated} from './gift-state.js';
import {PLAYLIST} from './playlist-gift.js';
export function setupSpeaker(svg){
 const ns='http://www.w3.org/2000/svg',speaker=document.createElementNS(ns,'g');speaker.setAttribute('transform','translate(173 827)');speaker.setAttribute('class','music-speaker');speaker.innerHTML=`<g transform="rotate(-10)"><path d="M-12 -111V-120Q-12 -125 -7 -125H8Q13 -125 13 -120V-111" fill="none" stroke="#354d49" stroke-width="5"/><rect x="-23" y="-114" width="46" height="117" rx="8" fill="#54736b" stroke="#354d49" stroke-width="3"/><rect x="-18" y="-107" width="36" height="104" rx="5" fill="#263e3b"/><path d="M-13 -99H4" stroke="#c8be96" stroke-width="2"/><circle cx="12" cy="-99" r="2" fill="#d2b87a"/><g fill="#667d70" stroke="#a3ac91" stroke-width="1.5"><circle cy="-76" r="16"/><circle cy="-32" r="19"/></g><g fill="#304b46" stroke="#354d49" stroke-width="2"><circle cy="-76" r="10"/><circle cy="-32" r="12"/></g><g fill="#b6b692"><circle cy="-76" r="4"/><circle cy="-32" r="5"/></g><path d="M-22 -110Q-15 -119 -5 -114Q5 -120 15 -114L22 -111" fill="#fffdf3" stroke="#e1e8d9" stroke-width="1.5"/><circle class="speaker-led" cx="13" cy="-8" r="2" fill="#a08c6e"/></g><path d="M-35 3Q-22 -8 -9 -3Q8 -11 28 -2L37 9Q3 18 -35 3Z" fill="#fffdf3"/>`;
 svg.append(speaker);
 const panel=document.createElement('section');panel.className='speaker-panel';panel.hidden=true;panel.setAttribute('aria-label','Christmas music');panel.innerHTML=`<button class="speaker-close" aria-label="Close music player">×</button><div id="speaker-player"></div><a href="${PLAYLIST}" target="_blank" rel="noopener noreferrer">Open in Spotify ↗</a>`;document.body.append(panel);
 const music=setupSpotifyPlayer(panel);
 window.addEventListener('spotify-connected',()=>{if(isFeatureActivated('boombox')){position();panel.hidden=false;}});
 window.addEventListener('spotify-auth-error',()=>{position();panel.hidden=false;});
 function position(){const box=speaker.getBoundingClientRect();panel.style.left=`${Math.max(12,Math.min(innerWidth-332,box.x+box.width/2-160))}px`;panel.style.bottom=`${Math.max(12,innerHeight-box.top+12)}px`;panel.style.maxHeight=`${Math.max(180,box.top-24)}px`;}
 function close(){panel.hidden=true;speaker.setAttribute('aria-expanded','false');}
 function open(){if(!isFeatureActivated('boombox'))return;position();panel.hidden=!panel.hidden;speaker.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){music.start();panel.querySelector('button').focus({preventScroll:true});}}
 function unlock(){const ready=isFeatureActivated('boombox');speaker.classList.toggle('unlocked',ready);speaker.setAttribute('role',ready?'button':'img');speaker.setAttribute('aria-label',ready?'Play your Christmas playlist':'Snowy speaker — opens with gift 1');speaker.setAttribute('tabindex',ready?'0':'-1');speaker.setAttribute('aria-disabled',String(!ready));}
 speaker.addEventListener('click',open);speaker.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});panel.querySelector('button').onclick=()=>{close();speaker.focus();};document.addEventListener('pointerdown',e=>{if(!panel.contains(e.target)&&!speaker.contains(e.target))close();});panel.addEventListener('keydown',e=>{if(e.key==='Escape'){close();speaker.focus();}});window.addEventListener('resize',position);window.addEventListener('gift-opened',unlock);window.addEventListener('gift-state-updated',unlock);unlock();
}
